private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType, Type ownerType) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    if (ownerType != null && ownerType instanceof ParameterizedType) {
        typeVariableMap.putAll(getTypeVariableMap(targetType, ((ParameterizedType) ownerType).getRawType()));
    }
    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        Type[] actualTypeArguments = ((ParameterizedType) genericSuperclass).getActualTypeArguments();
        TypeVariable<?>[] typeParameters = targetType.getSuperclass().getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            typeVariableMap.put(typeParameters[i], actualTypeArguments[i]);
        }
    }
    for (Type genericInterface : targetType.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            Type[] actualTypeArguments = ((ParameterizedType) genericInterface).getActualTypeArguments();
            TypeVariable<?>[] typeParameters = ((Class<?>) ((ParameterizedType) genericInterface).getRawType()).getTypeParameters();
            for (int i = 0; i < typeParameters.length; i++) {
                typeVariableMap.put(typeParameters[i], actualTypeArguments[i]);
            }
        }
    }
    return typeVariableMap;
}

