static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int month = monthDay / 100;
        int day = monthDay % 100;

        // Assuming the input is in YYYYMMDD format
        GregorianCalendar calendar = new GregorianCalendar(year, month - 1, day);
        calendar.add(Calendar.DAY_OF_MONTH, -(day % dayStep));
        int newDay = calendar.get(Calendar.DAY_OF_MONTH);
        int newMonth = calendar.get(Calendar.MONTH) + 1; // Calendar.MONTH is 0-based
        int newYear = calendar.get(Calendar.YEAR);

        return newYear * 10000 + newMonth * 100 + newDay;
    } catch (Exception e) {
        // Handle unexpected cases, e.g., invalid date format
        throw new IllegalArgumentException("Invalid timeBucket or dayStep value", e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length range");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4; // surrogate pair
            i++; // skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

