List<PathSegmentImpl> function ( URI u , boolean decode ) {
    if ( u == null ) {
        throw new IllegalArgumentException( "URI must not be null" );
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getRawPath();

    if ( path == null || path.isEmpty() ) {
        return pathSegments;
    }

    // If the path is absolute, skip the leading '/'
    int start = path.charAt( 0 ) == '/' ? 1 : 0;

    StringBuilder segmentBuilder = new StringBuilder();
    for ( int i = start; i < path.length(); i++ ) {
        char c = path.charAt( i );
        if ( c == '/' ) {
            String segment = segmentBuilder.toString();
            pathSegments.add( new PathSegmentImpl( decode ? decode( segment ) : segment, decode ) );
            segmentBuilder.setLength( 0 ); // reset the builder for the next segment
        } else {
            segmentBuilder.append( c );
        }
    }

    // Add the last segment if there is one
    if ( segmentBuilder.length() > 0 ) {
        String segment = segmentBuilder.toString();
        pathSegments.add( new PathSegmentImpl( decode ? decode( segment ) : segment, decode ) );
    }

    return pathSegments;
}

