void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    if (descriptor.startsWith("(")) {
        // It's a method descriptor, find the argument types
        int endIndex = descriptor.indexOf(')');
        if (endIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        String argumentTypes = descriptor.substring(1, endIndex);
        int index = 0;
        while (index < argumentTypes.length()) {
            char typeChar = argumentTypes.charAt(index);
            switch (typeChar) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'J':
                case 'S':
                case 'Z':
                    // These types take up one space
                    index++;
                    break;
                case 'L':
                case '[':
                    // References and arrays take up one space, but we need to skip their full descriptor
                    index = argumentTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid type descriptor in method descriptor: " + descriptor);
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + typeChar);
            }
        }
    } else {
        // It's a type descriptor, pop one
        // No action needed as we are assuming a single type is represented by a single descriptor character
    }
}

