public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at the end of the string.");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                default:
                    throw new Exception("Unsupported escape sequence: \\" + nextChar);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

