public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Neither 'path' nor 'relativePath' can be null.");
        }

        // Normalize both paths by removing trailing slashes
        path = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
        relativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

        // Split paths into components
        String[] pathComponents = path.split("/");
        String[] relativePathComponents = relativePath.split("/");

        // Stack to help navigate the path
        Stack<String> pathStack = new Stack<>();
        for (String component : pathComponents) {
            if (!component.isEmpty()) {
                pathStack.push(component);
            }
        }

        // Apply the relative path components
        for (String component : relativePathComponents) {
            if (component.equals("..")) {
                if (!pathStack.isEmpty()) {
                    pathStack.pop();
                }
            } else if (!component.equals(".")) {
                pathStack.push(component);
            }
        }

        // Build the final path
        StringBuilder result = new StringBuilder();
        for (String component : pathStack) {
            if (result.length() > 0) {
                result.append("/");
            }
            result.append(component);
        }

        return result.toString();
    } catch (Exception e) {
        throw new RuntimeException("Error applying relative path", e);
    }
}

